 // V4.8.9: purely visual lens. Small velocity lead and the nearest live threat
 // share the frame; HUD and touch targets never move. No camera zoom or physics.
 cameraTarget(game){
  const p=game.player;
  let x=clamp(p.x*.67,-8,8), y=p.y+5;
  if(game.phase!=='playing')return {x,y};
  x+=clamp((Number.isFinite(p.vx)?p.vx:0)*.12,-1.05,1.05);
  y+=clamp((Number.isFinite(p.vy)?p.vy:0)*.12,-.75,1.4);
  if(game.escape){
   const d=game.defenders.find(o=>o.id===game.escape.defenderId);
   if(d){x=clamp((p.x+d.x)*.335,-8,8);y=(p.y+d.y)*.5+5;}
  }else{
   let nearest=null, distance=196;
   for(const d of game.defenders){
    if(d.outForDrive||d.down||!Number.isFinite(d.x)||!Number.isFinite(d.y))continue;
    const dx=d.x-p.x,dy=d.y-p.y,ds=dx*dx+dy*dy;
    if(ds<distance){nearest=d;distance=ds;}
   }
   if(nearest){
    const weight=clamp(1-Math.sqrt(distance)/14,0,1);
    x+=clamp((nearest.x-p.x)*.17*weight,-.95,.95);
    y+=clamp((nearest.y-p.y)*.15*weight,-.8,.8);
   }
  }
  return {x:clamp(x,-8,8),y};
 }
project(x,y){return {x:this.w*.5+(x-this.camX)*this.scale+this.shakeX,y:this.h*.61-(y-this.camY)*this.sy+this.shakeY}}

function captureSnapshot(g){
 // Copy only render-relevant actors and the few labels they need. Never store
 // live actor references, accumulated event arrays or mutable particle lists.
 return {...g,phase:'playing',driveState:'',escape:null,
  player:{...g.player,cool:{...g.player.cool}},
  defenders:g.defenders.map(d=>({...d})),
  blockers:g.blockers.map(b=>({...b})),
  particles:g.particles.slice(-96).map(q=>({...q})),
  events:[],
  contactImpact:g.contactImpact?{...g.contactImpact}:null,
  lastDrive:g.lastDrive?{...g.lastDrive,breakdown:{...(g.lastDrive.breakdown||{})}}:null,
  formation:g.formation?{...g.formation}:null};
}

