// No simulation work or live-state read is allowed inside replay drawing.
function blendRecordedFrames(a,b,t){
 if(!b||t<=0||t>=1)return t>=1&&b?b:a;
 const mix=(first,last)=>{
  if(!last||!Number.isFinite(first.x)||!Number.isFinite(first.y)||!Number.isFinite(last.x)||!Number.isFinite(last.y))return first;
  // A vanished/displaced defender must never drift across the field.
  if(Math.hypot(last.x-first.x,last.y-first.y)>6)return first;
  const lerp=(u,v)=>Number.isFinite(u)&&Number.isFinite(v)?u+(v-u)*t:u;
  return {...first,x:lerp(first.x,last.x),y:lerp(first.y,last.y),
   vx:lerp(first.vx,last.vx),vy:lerp(first.vy,last.vy)};
 };
 const pair=(actors,following)=>{
  const byId=new Map(following.map(o=>[o.id,o]));
  return actors.map(o=>mix(o,byId.get(o.id)));
 };
 return {...a,player:mix(a.player,b.player),
  defenders:pair(a.defenders,b.defenders),
  blockers:pair(a.blockers,b.blockers)};
}
function showReplay(){
 if(!game.driveState||replay.active||replay.seenDrive===game.possession)return false;
 replay.seenDrive=game.possession;
 if(!replaysEnabled)return false;
 replay.kind=game.driveState;
 replay.frames=replay.history.slice(-(REPLAY_PLAYBACK_MAX-1)).concat([captureSnapshot(game)]);
 if(replay.frames.length<2)replay.frames=[captureSnapshot(game),captureSnapshot(game)];
 replay.time=0;
 const rate=replay.kind==='TOUCHDOWN'?1.34:1.20;
 replay.duration=reducedEffects?1.15:clamp(replay.frames.length*REPLAY_INTERVAL*rate,1.55,2.80);
 replay.active=true;acc=0;keys.clear();joy.x=joy.y=0;joyPointer=null;syncStick();setSprint(false);
 replayRenderer.lastPossession=-1;
 replayRenderer.shakeX=0;replayRenderer.shakeY=0;
 replayRenderer.resize();$('game').classList.add('replay-active');
 $('replayStage').classList.remove('hidden');$('replayStage').setAttribute('aria-hidden','false');
 setText('replayTitle',replay.kind==='TOUCHDOWN'?'TOUCHDOWN REPLAY':'TACKLE REPLAY');
 const moment=replay.kind==='TOUCHDOWN'?'THE FINISH':game.lastDrive?.breakdown?.counters?'CONTACT & COUNTER':'THE STOP';
 setText('replayDetail',`${reducedEffects?'STILL FRAME':'SLOW MOTION'} · ${moment} · POSSESSION ${game.possession}`);
 setText('liveState','Replay. Game clock frozen. Select Skip Replay to continue.');
 $('replaySkipBtn').focus({preventScroll:true});renderReplay(0);return true;
}
function renderReplay(dt){
 if(!replay.active)return;
 replay.time+=clamp(Number.isFinite(dt)?dt:0,0,.08);
 const ratio=clamp(replay.time/replay.duration,0,1);
 const length=replay.frames.length;
 // Final moment holds briefly; the other 90% interpolates recorded poses.
 const playback=clamp(ratio/.90,0,1)*(length-1);
 const index=Math.min(length-1,Math.floor(playback));
 const fraction=playback-index;
 const view=reducedEffects?replay.frames[length-1]:
  blendRecordedFrames(replay.frames[index],replay.frames[Math.min(length-1,index+1)],fraction);
 const closing=clamp((ratio-.76)/.13,0,1)*clamp((1-ratio)/.11,0,1);
 const amp=reducedEffects?0:(replayRenderer.w<550?1.1:1.7)*closing;
 replayRenderer.shakeX=amp*Math.sin(replay.time*66);
 replayRenderer.shakeY=amp*.5*Math.cos(replay.time*71);
 replayRenderer.draw(view,reducedEffects?0:dt*.72);
 $('replayProgress').style.width=(ratio*100).toFixed(1)+'%';
 if(replay.time>=replay.duration)finishReplay();
}
function finishReplay(){
 if(!replay.active)return false;
 const skipFocused=document.activeElement===$('replaySkipBtn');
 replay.active=false;replay.frames=[];replay.history=[];replay.kind='';
 replayRenderer.shakeX=0;replayRenderer.shakeY=0;
 $('replayStage').classList.add('hidden');$('replayStage').setAttribute('aria-hidden','true');
 $('game').classList.remove('replay-active');
 replay.lastPossession=0;acc=0;last=performance.now();uiTimer=0;
 setText('liveState','Replay finished. Next possession is ready.');
 if(skipFocused)(game.driveState&&!$('nextPlayBtn').disabled?$('nextPlayBtn'):canvas).focus({preventScroll:true});
 return true;
}
